// Package fonts carries the two serif families the break voice is set in:
// Spectral for Latin, and a Noto Serif SC subset for the Han characters the
// suggestions and the tagline use. The app registers them at startup; the
// UI keeps the system's own sans, so no interface text changes platform.
package fonts

import (
	"embed"
	"fmt"
	"sync"

	"github.com/egoist/mygo/ui"
)

// The subset files are generated by tools/fonts/subset.py from the OFL
// originals; their licenses sit beside them.
//
//go:embed assets/spectral-*.ttf assets/noto-serif-sc-*.otf
var files embed.FS

// A face is one weight of one family, registered under the name the design's
// font stack asks for.
type face struct {
	file   string
	family string
}

var faces = []face{
	{"assets/spectral-light.ttf", "Spectral"},
	{"assets/spectral-regular.ttf", "Spectral"},
	{"assets/noto-serif-sc-light.otf", "Noto Serif SC"},
	{"assets/noto-serif-sc-regular.otf", "Noto Serif SC"},
}

var (
	once sync.Once
	err  error
)

// Load registers the families with the UI's text system once per process. A
// second call returns the first call's error.
func Load() error {
	once.Do(func() {
		for _, f := range faces {
			data, e := files.ReadFile(f.file)
			if e != nil {
				err = fmt.Errorf("fonts: %s: %w", f.file, e)
				return
			}
			if e := ui.RegisterFont(data, f.family); e != nil {
				err = fmt.Errorf("fonts: %s: %w", f.file, e)
				return
			}
		}
	})
	return err
}
